 function renderList(){const validIds=new Set(estate.sites.map(s=>s.id));for(const id of selection)if(!validIds.has(id))selection.delete(id);const list=visible();$('#ls-count').textContent=totals(estate).sites;$('#ls-site-list').innerHTML=list.length?list.map(s=>{const p=effective(estate,s);return `<article class="ls-site-row ${s.id===selected?'active':''}">${selectionMode?`<label><input type="checkbox" data-ls-select="${esc(s.id)}" aria-label="Select ${esc(s.name)} for a shared edit" ${selection.has(s.id)?'checked':''}></label>`:''}<button data-ls-site="${esc(s.id)}"><span class="ls-site-icon">${s.type==='Factory'?'▥':'⌖'}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.city||s.country)} · ${esc(s.type)}${s.count>1?' · '+s.count+' sites':''}${!s.region||s.lat===null?' · Needs location review':''}</small><em>${p.products.length?p.products.length+' products':'Add requirements'}${p.exceptions?' · '+p.exceptions+' exceptions':''}</em></span><span class="ls-row-state ${p.products.length?'ready':''}">●</span></button></article>`;}).join(''):`<div class="ls-empty"><span>⌖</span><h3>${estate.sites.length?'No matching locations':'Start with somewhere real.'}</h3><p>${estate.sites.length?'Clear the filter to see all sites.':'London, Paris, New York. Or all your sites in one import.'}</p><button data-ls="add">Add your first location →</button></div>`;
 if(estate.unallocated)$('#ls-site-list').innerHTML+=`<div class="ls-unplaced"><strong>${estate.unallocated} sites not allocated</strong><p>Existing project count retained. Add location records to allocate them.</p></div>`;
 const shown=list.filter(s=>selection.has(s.id)).length;$('#ls-select-visible').checked=Boolean(list.length&&shown===list.length);$('#ls-select-visible').indeterminate=shown>0&&shown<list.length;$('#ls-select-visible').disabled=!list.length;$('#ls-bulk-tools').hidden=!selectionMode;const toggle=$('[data-ls=selection-mode]');toggle.textContent=selectionMode?'Done selecting sites':'Select sites to edit together';toggle.setAttribute('aria-expanded',String(selectionMode));toggle.disabled=!estate.sites.length;$('#ls-bulk-count').textContent=selection.size+' location '+(selection.size===1?'record':'records')+' selected'+(selection.size>shown?' ('+(selection.size-shown)+' outside this filter)':'');$('[data-ls=edit-selected]').disabled=!selection.size;const option=$('#ls-profile-scope option[value=selected]');if(option){option.textContent='Selected records ('+selection.size+')';option.disabled=!selectionMode||!selection.size;}$('#ls-progress').textContent=totals(estate).sites+' sites · '+selection.size+' selected · '+read().selectedProviders.length+' shortlisted';}
