 function planningText(target=estate){return estatePlanningText(target,read().input,siteDrafts.size);}
 function userFields(){const i=read().input,u=estate.planning?.users??{count:i.users||0,remote:0,groups:'',regions:'',requirements:''};return heading('Users and shared security services','Count each person once. Remote workers are part of that population, not extra users at every site.')+`<form id="ls-users-form"><div class="ls-two">${field('Unique users in scope','count',u.count,'number')}${field('Of these, remote users','remote',u.remote,'number')}</div>${field('User groups and feature needs','groups',u.groups,'textarea')}${field('Countries / regions where users work','regions',u.regions,'textarea')}${field('Applications, access needs and existing licences to retain','requirements',u.requirements,'textarea')}<p class="ls-hint">Selected products: ${esc(i.products.filter(p=>p.included).map(p=>productLabel(p.id)).join('; '))}. Network-only projects can record zero licensed users and explain that scope.</p><button class="ls-primary" type="submit">Confirm users & update RFP →</button></form>`;}
 function renderProviderBorder(){const r=readiness(),d=read(),providers=providerFrameEntries(d);for(const [edge,index]of [['top',0],['right',1],['bottom',2],['left',3]]){const el=$('#ls-provider-'+edge);el.hidden=false;el.setAttribute('role','group');el.setAttribute('aria-label','Provider frame '+edge);el.innerHTML=providers.filter((p,i)=>i%4===index).map(p=>{const fit=providerFitStatus(p,r,d);return `<button class="ls-border-provider ls-fit-${fit.kind}" data-ls-evidence="${esc(p.slug)}" data-fit="${fit.kind}" aria-pressed="${panel==='evidence'&&evidence?.slug===p.slug}" aria-label="${esc(providerFrameLabel(p)+'. '+fit.label+'. Open reasons and research')}"><strong title="${esc(p.name)}">${esc(providerFrameLabel(p))}</strong><small><i aria-hidden="true"></i>${esc(fit.label)}</small></button>`;}).join('');}$('#ls-provider-border-status').textContent=(providers.length?providers.length+' vendors and managed providers · ':'Loading provider catalogue · ')+(!r.ready?'Awaiting your scope: '+r.missing.join(' · '):d.busy?'Updating provider evidence for this estate…':d.error?'Assessment unavailable. No current fit is claimed.': 'Green: assessed fit evidenced · Amber: needs confirmation · Red: confirmed mismatch. Site delivery and design need supplier confirmation.');}

 function renderDocument(force=false){const paper=document.querySelector('#ns-living-preview');if(!paper)return;const existing=paper.querySelector('#ls-document-estate');if(!force&&existing?.contains(document.activeElement))return;const expanded=new Set([...(existing?.querySelectorAll('details[open]')??[])].map(d=>d.dataset.site));existing?.remove();const section=document.createElement('section');section.id='ls-document-estate';const paged=estatePage(estate.sites,documentPage,pageSize);documentPage=paged.page;section.innerHTML='<h3>Site and user scope review</h3><pre class="ls-scope-review">'+esc(estateReviewPlan(estate,read().input,siteDrafts.size))+'</pre><button type="button" data-ls-review-users>Review users and shared services</button><h3>Shared and assigned plans</h3>'+estatePlans(estate,defs()).map(p=>'<h4>'+esc(p.label)+'</h4><pre>'+esc(p.text)+'</pre>').join('')+'<button type="button" data-ls-edit-shared>Edit shared plan</button><h3>Location schedule</h3>'+pagination(paged,'document')+'<p>Word and text exports include all '+estate.sites.length+' locations, regardless of this page or filters.</p><p>Edit these site records directly. Saved changes update the geographic map, the provider comparison and this RFP. City-level positions are approximate.</p>'+(estate.example?'<p><strong>Illustrative example locations. Replace fictional details before supplier sharing.</strong></p>':'')+paged.sites.map(s=>{const p=effective(estate,s),draft=siteDrafts.get(s.id),v=k=>draft&&Object.hasOwn(draft,k)?draft[k]:s[k];return `<details data-site="${esc(s.id)}" ${expanded.has(s.id)?'open':''}><summary>${esc(s.name)} · ${esc(s.city)} · ${s.count} site(s) · ${siteExceptionLines(estate,s,defs()).length} exceptions</summary><form data-ls-document-site="${esc(s.id)}"><p>Plan: ${esc(s.profileRef|| (estate.groups[s.type]?'Group '+s.type:'Shared estate plan'))}. ${esc(siteExceptionLines(estate,s,defs()).join('; ')||'No site exceptions.')}</p>${field('Location name','name',v('name'))}${field('Known users','users',draft?.users??s.users??'','number')}${field('Applications','apps',v('apps'))}${field('Cloud services','clouds',v('clouds'))}${field('Existing connectivity','circuit',v('circuit'),'textarea')}${field('Site requirements','notes',v('notes'),'textarea')}${field('Bandwidth / capacity','bandwidth',draft?.bandwidth??sitePlanning(estate,s).bandwidth)}${field('Resilience','resilience',draft?.resilience??sitePlanning(estate,s).resilience,'textarea')}<h4>Primary and backup connectivity</h4>${networkFields(sitePlanning(estate,s).connectivity,'',draft)}<p>Required products. Changes here create local exceptions.</p><div class="ls-doc-products">${defs().map(d=>`<label><input type="checkbox" name="product:${d.id}" ${(draft?Object.hasOwn(draft,'product:'+d.id):p.products.includes(d.id))?'checked':''}>${esc(d.label)}</label>`).join('')}</div><button type="submit">Save this site in RFP and map</button></form></details>`;}).join('');paper.append(section);section.querySelector('[data-ls-edit-shared]').onclick=()=>{panel='profile';draftProfile=null;renderInspector();host.scrollIntoView({block:'start'});};section.addEventListener('input',e=>{const f=e.target.closest('[data-ls-document-site]');if(f){siteDrafts.set(f.dataset.lsDocumentSite,{...Object.fromEntries(new FormData(f)),_document:'1'});$('#ls-estate-stats').textContent=estate.sites.length+' mapped records · '+siteDrafts.size+' unsaved site edits';}});section.querySelector('[data-ls-review-users]').addEventListener('click',()=>{panel='users';renderInspector();host.scrollIntoView({behavior:'smooth',block:'start'});});for(const compiled of root.querySelectorAll('[data-custom-text="location-estate-schedule"]')){compiled.readOnly=true;compiled.setAttribute('aria-label','Compiled location schedule. Edit the structured location schedule below.');}section.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const f=e.target,sid=f.dataset.lsDocumentSite;if(!sid)return;try{const d=Object.fromEntries(new FormData(f)),next=clone(estate),s=next.sites.find(s=>s.id===sid);Object.assign(s,{name:d.name,users:Number(d.users)||0,apps:d.apps,clouds:d.clouds,circuit:d.circuit,notes:d.notes,bandwidth:d.bandwidth,resilience:d.resilience,connectivity:networkPlanFromFields(d)});const previous=effective(estate,estate.sites.find(s=>s.id===sid));for(const def of defs()){const included=Object.hasOwn(d,'product:'+def.id);if(included!==previous.products.includes(def.id))s.overrides[def.id]=included;}const pending=siteDrafts.get(sid);siteDrafts.delete(sid);document.activeElement?.blur();if(!change(next,'Living RFP site saved. The location map and provider comparison use the same record.')){if(pending)siteDrafts.set(sid,pending);return;}renderDocument();}catch(err){status(err.message);if(locationImport){importError=err.message;renderImportReview();$('#ls-import-error')?.focus();$('#ls-import-error')?.scrollIntoView({block:'nearest'});}}});}
 function refresh(){renderGoal();renderProviderBorder();const current=read(),signature=productSignature(current.input.products??[]);if(!syncing&&!restoring){let changed=false;const productsChanged=signature!==lastCoreProducts;if(productsChanged){estate.defaults.products=(current.input.products??[]).filter(p=>p.included).map(p=>p.id);estate.defaults.features=Object.fromEntries((current.input.products??[]).filter(p=>p.included).map(p=>[p.id,[...p.features]]));lastCoreProducts=signature;changed=true;}if(current.input.sites!==totals(estate).sites){try{estate=reconcileEstateTotal(estate,current.input.sites);changed=true;}catch(error){status(error.message);}}if(changed){saved='';sync(false,true);renderList();renderVisual();status(productsChanged?'Business-wide product edit applied to inherited defaults. Local and group exceptions are preserved.':'Site count updated from the Living RFP. Named locations are preserved.');}}const count=totals(estate);$('#ls-estate-stats').textContent=count.placed+' mapped records · '+count.exceptions+' product exceptions · '+(saved&&read().saved?'Saved on this device':'Unsaved changes');renderDocument();if(panel==='providers'||panel==='evidence')renderInspector();renderGoal();renderProviderBorder();const d=read();refreshSectorButtons();$('#ls-progress').textContent=totals(estate).sites+' sites · '+selection.size+' selected · '+d.selectedProviders.length+' shortlisted';}
 // Restore only this preview's saved project through the existing validation boundary.
 let stored=null;try{stored=localStorage.getItem(key);}catch{error='This browser cannot read device storage. Your project can still be edited in memory. Download a backup before leaving.';}if(stored&&!new URLSearchParams(location.search).has('core')){try{const raw=JSON.parse(stored);estate=validateEstate(raw.estate);restoreSiteDrafts(raw.siteDrafts);saved='saved';restoring=true;bridge.restore(raw.connectedProject).then(()=>{restoring=false;sync();render();fit();status('Saved location estate and connected project reopened on this device.');}).catch(e=>{restoring=false;status('Saved project could not be fully reopened: '+e.message);});}catch{status('Saved location data could not be read. It has not been overwritten.');}}
 function navigate(id){if(legacy.open)return false;if(['written-brief','questions','timing','instructions','document-business'].includes(id)){host.classList.remove('ls-focused');$('[data-ls=expand]').textContent='⛶ Expand map';document.querySelector('#ns-living-rfp').scrollIntoView({behavior:'smooth'});return true;}if(id==='research-library'||id.startsWith('knowledge:')||id==='company-overview'||id==='sector-challenges'||/^c\d+$/.test(id)){legacy.open=true;return false;}if(['scope','project','sector','estate','coverage','business','optional-details','apps','clouds','technology','operating','project-shortlist'].includes(id)||id.startsWith('provider:')||id.startsWith('product:')||id.startsWith('feature:')){selected=null;if(id==='project-shortlist'||id.startsWith('provider:')){if(!readiness().ready){openGoalNext();return true;}evidence=read().providers.find(p=>p.slug===id.slice(9));panel=evidence?'evidence':'providers';}else if(id==='scope'||id.startsWith('product:')||id.startsWith('feature:')){panel='profile';draftProfile=null;}else if(['estate','coverage'].includes(id))panel='add';else panel='business';render();host.scrollIntoView({behavior:'smooth',block:'start'});return true;}legacy.open=true;return false;}
 checkLocationAI();loadPresence();render();registerEstateBrowserTools();new ResizeObserver(resizeMap).observe($('#ls-map'));return {refresh,renderDocument,navigate,readiness,element:host,export:()=>clone(estate),exportCore:()=>({version:'netify-core-snapshot/1',estate:clone(estate),siteDrafts:Object.fromEntries(siteDrafts),packet:bridge.packet()}),restoreCore:async raw=>{const rawCopy=clone(raw);const next=normaliseEstate(rawCopy.estate,rawCopy.packet.project.input);detachLegacySchedule(rawCopy.packet,next,defs());restoring=true;try{estate=next;restoreSiteDrafts(raw.siteDrafts);await bridge.restore(rawCopy.packet);}finally{restoring=false;}lastCoreProducts=productSignature(bridge.read().input.products??[]);render();fit();},coreRevision:revision=>bridge.savedRevision?.(revision),coreStatus:text=>{status(text);const badge=host.querySelector('.ls-private');if(badge)badge.textContent=text;},countWarning:()=>read().input.sites<estate.sites.reduce((n,s)=>n+s.count,0)?'The site total is lower than your location records. Review the site count before exporting.':'',beginBrief:()=>{goal='shortlist';goalChosen=true;selected=null;panel='quick';render();host.scrollIntoView({block:'start'});requestAnimationFrame(()=>host.querySelector('#ls-quick-form [data-ls-sector]')?.focus({preventScroll:true}));},openComparison:()=>{goal='shortlist';goalChosen=true;openGoalNext();return readiness().ready;},openRfp:()=>{goal='rfp';goalChosen=true;bridge.rfp();host.classList.remove('ls-focused');document.querySelector('#ns-living-rfp').scrollIntoView({block:'start'});}};
